"""Tests for tasks_api.models — Tag, Task, TaskPriority, TaskStatus, is_overdue."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from .conftest import FIXED_NOW


# ── TaskStatus / TaskPriority enums ──────────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_from_string(self):
        assert TaskStatus("pending") is TaskStatus.PENDING
        assert TaskStatus("done") is TaskStatus.DONE


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_first(self):
        keys = [TaskPriority.order_key(p) for p in TaskPriority]
        assert keys == [0, 1, 2]  # LOW=0? No: enum order is LOW, MEDIUM, HIGH
        # Actually enum iteration order is LOW, MEDIUM, HIGH
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.LOW)

    @pytest.mark.parametrize("priority,expected", [
        (TaskPriority.HIGH, 0),
        (TaskPriority.MEDIUM, 1),
        (TaskPriority.LOW, 2),
    ])
    def test_order_key_values(self, priority, expected):
        assert TaskPriority.order_key(priority) == expected


# ── Tag ──────────────────────────────────────────────────────────────────

class TestTag:
    def test_valid_tag(self):
        tag = Tag("Work")
        assert tag.name == "work"

    def test_strips_whitespace(self):
        tag = Tag("  hello  ")
        assert tag.name == "hello"

    def test_lowercases(self):
        tag = Tag("BIG")
        assert tag.name == "big"

    def test_allows_hyphens_underscores_digits(self):
        tag = Tag("my-tag_2")
        assert tag.name == "my-tag_2"

    def test_empty_name_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_exactly_32_chars_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_character_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")  # space is illegal

    @pytest.mark.parametrize("bad_name", ["tag!", "tag@home", "tag.name", "tag/path"])
    def test_various_illegal_chars(self, bad_name):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad_name)


# ── Task ─────────────────────────────────────────────────────────────────

class TestTask:
    def test_defaults(self):
        t = Task(id=1, title="Do stuff")
        assert t.status == TaskStatus.PENDING
        assert t.priority == TaskPriority.MEDIUM
        assert t.due_at is None
        assert t.completed_at is None
        assert t.tags == []
        assert t.created_at is not None

    def test_is_overdue_no_due_date(self):
        t = Task(id=1, title="No due", due_at=None, created_at=FIXED_NOW)
        assert t.is_overdue(FIXED_NOW) is False

    def test_is_overdue_done_task(self):
        past = FIXED_NOW - timedelta(days=1)
        t = Task(id=1, title="Done", status=TaskStatus.DONE, due_at=past, created_at=FIXED_NOW)
        assert t.is_overdue(FIXED_NOW) is False

    def test_is_overdue_past_due(self):
        past = FIXED_NOW - timedelta(days=1)
        t = Task(id=1, title="Late", due_at=past, created_at=FIXED_NOW)
        assert t.is_overdue(FIXED_NOW) is True

    def test_is_overdue_future_due(self):
        future = FIXED_NOW + timedelta(days=1)
        t = Task(id=1, title="On time", due_at=future, created_at=FIXED_NOW)
        assert t.is_overdue(FIXED_NOW) is False

    def test_is_overdue_exactly_now(self):
        # due_at == now  →  due_at < now is False → not overdue
        t = Task(id=1, title="Edge", due_at=FIXED_NOW, created_at=FIXED_NOW)
        assert t.is_overdue(FIXED_NOW) is False

"""Tests for tasks_api.queries — TaskQuery, TaskPage, apply_query."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query
from .conftest import FIXED_NOW, make_task


# ── TaskQuery validation ─────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "name", "updated_at", ""])
    def test_invalid_sort_field(self, bad_sort):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("valid_sort", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, valid_sort):
        q = TaskQuery(sort=valid_sort)
        assert q.sort == valid_sort

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "ten"])
    def test_invalid_limit(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    def test_valid_limit_boundaries(self):
        assert TaskQuery(limit=1).limit == 1
        assert TaskQuery(limit=100).limit == 100

    @pytest.mark.parametrize("bad_offset", [-1, "zero"])
    def test_invalid_offset(self, bad_offset):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=bad_offset)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_is_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage ─────────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[make_task()], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[make_task()], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_empty(self):
        page = TaskPage(items=[], total=0, limit=20, offset=0)
        assert page.has_more is False


# ── apply_query filtering ────────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        past = FIXED_NOW - timedelta(days=1)
        future = FIXED_NOW + timedelta(days=1)
        return [
            make_task(id=1, title="Buy milk", status=TaskStatus.PENDING, due_at=past, tags=[Tag("shopping")]),
            make_task(id=2, title="Write report", status=TaskStatus.DONE, due_at=future, tags=[Tag("work")]),
            make_task(id=3, title="Clean house", status=TaskStatus.PENDING, due_at=future, tags=[Tag("home")]),
            make_task(id=4, title="Buy eggs", status=TaskStatus.PENDING, due_at=None, tags=[Tag("shopping"), Tag("food")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), FIXED_NOW)
        assert page.total == 4

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), FIXED_NOW)
        assert page.total == 3
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), FIXED_NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), FIXED_NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), FIXED_NOW)
        assert page.total == 2

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), FIXED_NOW)
        # All tasks that are NOT overdue: task 2 (done), task 3 (future), task 4 (no due)
        assert page.total == 3

    def test_combined_filters(self, tasks):
        page = apply_query(
            tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping"),
            FIXED_NOW,
        )
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}


# ── apply_query sorting ─────────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        base = FIXED_NOW
        return [
            make_task(id=1, title="Charlie", priority=TaskPriority.LOW,
                      created_at=base + timedelta(hours=2), due_at=base + timedelta(days=3)),
            make_task(id=2, title="Alpha", priority=TaskPriority.HIGH,
                      created_at=base + timedelta(hours=1), due_at=base + timedelta(days=1)),
            make_task(id=3, title="Bravo", priority=TaskPriority.MEDIUM,
                      created_at=base, due_at=None),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), FIXED_NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), FIXED_NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), FIXED_NOW)
        assert [t.title for t in page.items] == ["Alpha", "Bravo", "Charlie"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), FIXED_NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW,
        ]

    def test_sort_by_due_at_none_sorts_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), FIXED_NOW)
        # None due_at should sort last
        assert page.items[-1].id == 3
        assert page.items[-1].due_at is None


# ── apply_query pagination ───────────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [make_task(id=i, title=f"Task {i}") for i in range(1, 6)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), FIXED_NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=3), FIXED_NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is False

    def test_offset_past_end(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=10, offset=10), FIXED_NOW)
        assert len(page.items) == 0
        assert page.total == 5
        assert page.has_more is False

    def test_full_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=100), FIXED_NOW)
        assert len(page.items) == 5
        assert page.has_more is False

